import pytest
from http import HTTPStatus


@pytest.mark.parametrize(
    "api_key, expected_status_code, description",
    [
        ("valid_key", HTTPStatus.OK, "Valid API key - Logout Successful."),
        ("invalid_key", HTTPStatus.UNAUTHORIZED, "Invalid API key - Unauthorized."),
        (None, HTTPStatus.UNAUTHORIZED, "Missing API key - Unauthorized."),
    ],
)
def test_user_logout(
    api_client,
    valid_api_key,
    invalid_api_key,
    api_key,
    expected_status_code,
    description,
):
    """
    Test the /user/logout endpoint.

    Covers:
    - Valid API key (Successful logout)
    - Invalid API key (Unauthorized)
    - Missing API key (Unauthorized)
    """
    # Define endpoint
    endpoint = "/user/logout"

    # Select API key based on the param
    if api_key == "valid_key":
        headers = {"Authorization": f"Bearer {valid_api_key}"}
    elif api_key == "invalid_key":
        headers = {"Authorization": f"Bearer {invalid_api_key}"}
    else:
        headers = {}

    # Send the request
    response = api_client.get(endpoint, headers=headers)

    # Assert the status code
    assert response.status_code == expected_status_code, (
        f"Unexpected response code for {description}. "
        f"Got: {response.status_code}, Expected: {expected_status_code}"
    )

    # Provide additional checks for success scenario
    if response.status_code == HTTPStatus.OK:
        assert response.text == "", "Logout endpoint should return an empty response body."


@pytest.mark.parametrize(
    "api_key, retries",
    [
        ("valid_key", 3),
        ("invalid_key", 0),
    ],
)
def test_user_logout_with_retries(api_client, valid_api_key, invalid_api_key, api_key, retries):
    """
    Test the /user/logout endpoint with retry logic.
    """
    endpoint = "/user/logout"
    headers = {
        "Authorization": f"Bearer {valid_api_key if api_key == 'valid_key' else invalid_api_key}"
    }

    for attempt in range(retries):
        response = api_client.get(endpoint, headers=headers)

        if response.status_code == HTTPStatus.OK:
            break

    if api_key == "valid_key":
        assert response.status_code == HTTPStatus.OK
    else:
        assert response.status_code == HTTPStatus.UNAUTHORIZED
